'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const date=()=>new Date().toISOString(), fmt=d=>new Date(d).toLocaleString('fr-FR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const seed=window.WOR_ASSETS;
let state,view='board',activeId,editorAsset,editorVersion,editorTab='feedback',draftPin=null,category='Général',mobile=false,busy=false,uploadIntent=null,db=null,server=false,token='',revision=0,saveChain=Promise.resolve(),renderTicket=0;
const previewCache=new Map(),imageCache=new Map();
const initial=()=>({schema:1,activeId:'candace',episodes:[{id:'candace',name:'Candace Lau',subject:'The reality of prop trading',frameio:'',transcript:'',created:date(),sourceNotes:'Exemples existants issus des dossiers WOR. Les titres sont repris des visuels ; vérifier les affirmations dans le transcript avant publication.',assets:Object.entries(seed).filter(([,v])=>v.kind==='thumbnail').map(([id,a])=>({id,kind:'thumbnail',name:a.label,headline:a.title,versions:[{id:uid(),created:date(),source:id,width:a.width,height:a.height,label:'Master existant',status:'review',comments:[]}]})),sources:[],selected:null}]});
const ep=()=>state.episodes.find(x=>x.id===activeId)||state.episodes[0];
const assets=()=>ep().assets;
const latest=a=>a.versions.at(-1);
const version=(a,id)=>a.versions.find(v=>v.id===id)||latest(a);
const selected=()=>ep().selected&&assets().find(a=>a.id===ep().selected.assetId);
const allComments=()=>state.episodes.flatMap(e=>e.assets.flatMap(a=>a.versions.flatMap((v,i)=>v.comments.map(c=>({e,a,v,i,c})))));
const source=v=>v.source?seed[v.source].src:v.data;
const dims=k=>k==='thumbnail'?[3840,2160]:k==='story'?[1080,1920]:[1080,1080];
const label=k=>({thumbnail:'Thumbnail',story:'Story',spotify:'Spotify'}[k]||k);
const versionLabel=(a,v)=>`V${String(a.versions.indexOf(v)+1).padStart(2,'0')}`;
const statusBadge=v=>v.status==='approved'?'<span class="badge green">✓ Validé</span>':v.status==='changes'?'<span class="badge orange">À retoucher</span>':'<span class="badge">À examiner</span>';
function toast(s){const dialog=$('dialog[open]');if(dialog){$('.dialog-notice',dialog)?.remove();const note=document.createElement('div');note.className='dialog-notice';note.setAttribute('role','status');note.textContent=s;dialog.appendChild(note);setTimeout(()=>note.remove(),5000)}$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function download(data,name,type){const b=data instanceof Blob?data:new Blob([data],{type:type||'text/plain;charset=utf-8'});const url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function validState(s){return s?.schema===1&&Array.isArray(s.episodes)&&s.episodes.length>0&&s.episodes.every(e=>typeof e.id==='string'&&typeof e.name==='string'&&Array.isArray(e.sources)&&Array.isArray(e.assets)&&e.assets.every(a=>['thumbnail','story','spotify'].includes(a.kind)&&Array.isArray(a.versions)&&a.versions.length&&a.versions.every(v=>typeof v.id==='string'&&Array.isArray(v.comments)&&(v.source in seed||/^data:image\/(png|jpeg|webp);base64,/.test(v.data||'')))))}
async function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('wor-studio-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('state');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function dbRead(){if(!db)return null;return new Promise((resolve,reject)=>{const req=db.transaction('state').objectStore('state').get('project');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function dbWrite(s){if(!db)throw Error('Stockage navigateur indisponible');return new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite');tx.objectStore('state').put(s,'project');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function persist(){state.activeId=activeId;const snapshot=structuredClone(state);$('#save-status').textContent='Enregistrement…';saveChain=saveChain.catch(()=>{}).then(async()=>{let localOK=false;try{await dbWrite(snapshot);localOK=true}catch{}if(server){const r=await fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json','X-WOR-Token':token},body:JSON.stringify({state:snapshot,revision})});if(!r.ok)throw Error(r.status===409?'Autre onglet modifié : sauvegardez un fichier avant de recharger.':'Échec de sauvegarde sur disque.');const data=await r.json();revision=data.revision;$('#save-status').textContent='✓ Enregistré sur cet ordinateur'}else if(localOK){$('#save-status').textContent='✓ Enregistré dans ce navigateur'}else{throw Error('Sauvegarde indisponible. Utilisez ↓ Sauvegarder.')}}).catch(e=>{$('#save-status').textContent='Sauvegarde à vérifier';toast(e.message)});return saveChain}
async function loadImage(src){if(!imageCache.has(src))imageCache.set(src,new Promise((res,rej)=>{const im=new Image();im.onload=()=>res(im);im.onerror=()=>rej(Error('Impossible de lire cette image'));im.src=src}));return imageCache.get(src)}
// Uniform, monochrome noise in [-0.03*255,+0.03*255]. Always rendered from an immutable clean version.
function grain(ctx,w,h){const im=ctx.getImageData(0,0,w,h);let rng=48271;for(let p=0;p<im.data.length;p+=4){rng=(Math.imul(rng,1664525)+1013904223)|0;const n=(((rng>>>0)/4294967295)*2-1)*255*.03;im.data[p]+=n;im.data[p+1]+=n;im.data[p+2]+=n}ctx.putImageData(im,0,0)}
function fit(ctx,img,x,y,w,h){const s=Math.min(w/img.width,h/img.height);ctx.drawImage(img,x+(w-img.width*s)/2,y+(h-img.height*s)/2,img.width*s,img.height*s)}
async function raster(v,kind,preview=false){const [w0,h0]=dims(kind),scale=preview?Math.min(1,1000/w0,1000/h0):1,w=Math.round(w0*scale),h=Math.round(h0*scale);const c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.fillStyle='#111';ctx.fillRect(0,0,w,h);fit(ctx,await loadImage(source(v)),0,0,w,h);if(!v.grainBaked)grain(ctx,w,h);return c}
async function preview(a,v=latest(a)){const key=v.id;if(!previewCache.has(key)){previewCache.set(key,raster(v,a.kind,true).then(c=>c.toDataURL('image/jpeg',.9)))}return previewCache.get(key)}
async function paintImages(root=document){await Promise.allSettled($$('[data-preview]',root).map(async im=>{const a=assets().find(x=>x.id===im.dataset.preview);if(!a)return;const v=version(a,im.dataset.version);const url=await preview(a,v);if(im.isConnected)im.src=url}))}
function head(kicker,title,subtitle,actions=''){return `<section class="hero"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="hero-actions">${actions}</div></section>`}
function episodeLine(){return `<div class="episode-line"><div class="episode-selector"><span class="brand-square">${esc(ep().name[0])}</span><div><label for="episode-select">ÉPISODE EN COURS</label><select id="episode-select">${state.episodes.map(e=>`<option value="${esc(e.id)}" ${e.id===ep().id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></div><button class="button small" id="edit-brief">Brief ↗</button></div><span class="badge">${assets().length} visuels · WOR</span></div>`}
function card(a){const v=latest(a),isSelected=ep().selected?.assetId===a.id&&ep().selected.versionId===v.id;return `<article class="asset-card ${isSelected?'selected':''}"><button class="asset-visual" data-open="${a.id}" aria-label="Examiner ${esc(a.name)}"><img data-preview="${a.id}" alt="${esc(a.headline||a.name)}"><span class="version">${versionLabel(a,v)} · ${a.versions.length>1?'Nouvelle version':'Master'}</span><span class="view-pill">↗ Examiner</span></button><div class="asset-info"><h3>${esc(a.name)}</h3><div class="asset-sub"><span>${v.width} × ${v.height} · ${v.comments.filter(c=>!c.resolved).length} retours</span>${statusBadge(v)}</div><div class="card-actions"><button class="button" data-open="${a.id}">◉ Donner un retour</button><button class="button ${isSelected?'green':''}" data-select="${a.id}">${isSelected?'✓ Sélectionné':'Choisir →'}</button></div></div></article>`}
function derivative(kind){const parent=ep().selected;const a=assets().filter(x=>x.kind===kind&&x.parentAssetId===parent?.assetId&&x.parentVersionId===parent?.versionId).at(-1);return `<article class="derivative-panel"><${a?'button':'div'} class="derivative-preview" ${a?`data-open="${a.id}" aria-label="Examiner ${label(kind)}"`:''}>${a?`<img data-preview="${a.id}" alt="Déclinaison ${label(kind)}">`:`<div class="format-placeholder ${kind==='spotify'?'square':''}">${kind==='story'?'9:16':'1:1'}</div>`}</${a?'button':'div'}><div class="derivative-content"><span class="meta-caps">${kind==='story'?'INSTAGRAM · 9:16':'PODCAST · 1:1'}</span><h3>${kind==='story'?'La Story':'La cover Spotify'}</h3>${a?statusBadge(latest(a)):''}<p>${a?'Mise en page automatique à examiner.':"Le format se prépare après validation du thumbnail."}<br>${dims(kind).join(' × ')} px</p>${a?`<button class="button small" data-open="${a.id}">Examiner & ajuster ↗</button>`:'<span class="badge">↳ Attend le thumbnail</span>'}</div></article>`}
function render(){if(view!=='youtube')document.body.classList.remove('feed-focus');const titles={ab:'Prétest des miniatures',titles:'Prétest des titres',youtube:'Dans YouTube',board:'Atelier',library:'Sources & références',feedback:'Mes retours',rules:'Règles créatives'};$('#crumb').textContent=titles[view];$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#feedback-count').textContent=allComments().filter(x=>!x.c.resolved).length;
 const a=selected(),sv=a&&version(a,ep().selected.versionId);let html='';
 if(view==='board'){html=head('L’ATELIER WORDS OF RIZDOM','Un épisode. Tous ses visuels.','Choisis une direction, affine le détail, décline le reste.',`<button class="button" id="new-episode">＋ Nouvel épisode</button>`)+episodeLine()+`<div class="pipeline"><button class="step ${!sv?'current':''}" id="step-thumb"><span class="step-number">${sv?.status==='approved'?'✓':'01'}</span><div><strong>Le thumbnail</strong><small>Explorer, commenter, choisir</small></div><span class="arrow">→</span></button><button class="step ${sv?'current':''}" id="step-derive"><span class="step-number">02</span><div><strong>Les déclinaisons</strong><small>Story + Spotify, même direction</small></div><span class="arrow">→</span></button><button class="step" id="step-export"><span class="step-number">03</span><div><strong>Le pack final</strong><small>Vérifier et télécharger</small></div><span class="arrow">↗</span></button></div><div class="section-head"><div><h2>Une direction à choisir<span class="count">${assets().filter(x=>x.kind==='thumbnail').length} propositions</span></h2><p>Clique sur un visuel pour l’agrandir et annoter directement dessus.</p></div><div class="section-tools"><span class="badge">◌ Grain 3 %</span><button class="button small" id="import-thumb">＋ Importer</button></div></div><section class="grid" id="thumbnail-grid">${assets().filter(x=>x.kind==='thumbnail').map(card).join('')}</section>${!assets().some(x=>x.kind==='thumbnail')?'<div class="empty"><h2>Le premier visuel commence ici.</h2><p>Ajoute un thumbnail existant, ou prépare le brief de création.</p><button class="button primary" id="empty-import">Importer un thumbnail</button><button class="button" id="prepare-brief">Préparer le brief IA</button></div>':''}<div class="bridge"><div class="bridge-icon">↳</div><div><strong>${sv?'Ta direction est choisie. Place aux déclinaisons.':'Le thumbnail donne le ton.'}</strong><p>${sv?esc(a.name)+' · '+versionLabel(a,sv):'Une fois validé, la Story et Spotify se préparent ensemble, avec 3 % de grain.'}</p></div>${sv?'<button class="button primary small" id="generate">Valider et décliner →</button>':'<span class="badge">À toi de choisir</span>'}</div><div class="section-head" id="derivatives-heading"><div><h2>La suite, naturellement.</h2><p>Deux formats reliés à la version de thumbnail sélectionnée.</p></div></div><section class="derivatives">${derivative('story')}${derivative('spotify')}</section><div class="rule-strip"><span>Versions originales conservées</span><span>Retours liés à chaque image</span><span>Grain 3 % à l’export</span><button class="text-button" id="mode-help">Mode local : ce qui est automatique ↗</button></div>`;}
 if(view==='library'){html=head('LES FONDATIONS','Tout part des bonnes sources.','Photos originales, transcript et références : réunis le brief de l’épisode.',`<button class="button" id="import-sources">＋ Ajouter des photos</button>`)+episodeLine()+`<div class="panel"><div class="section-head"><h2>Brief · ${esc(ep().name)}</h2><button class="button small" id="edit-brief">Modifier ↗</button></div><p>${esc(ep().subject||'Sujet à compléter')}</p><p>${ep().frameio?`Lien Frame.io : ${esc(ep().frameio)}`:'Aucun lien Frame.io ajouté.'}</p><span class="badge">${ep().transcript?ep().transcript.length+' caractères de transcript':'Transcript à ajouter'}</span><p class="muted">Les photos importées restent intactes. Les références ci-dessous servent au style ; les visages et les chiffres doivent venir du nouvel épisode.</p></div><div class="section-head"><h2>Photos de l’épisode <span class="count">${ep().sources.length}</span></h2><button class="button small" id="import-source-more">＋ Importer</button></div><div class="library-grid">${ep().sources.map(s=>`<article class="library-item"><img src="${esc(s.data)}" alt="${esc(s.name)}"><div><h3>${esc(s.name)}</h3><p>${s.width} × ${s.height} · Original conservé</p></div></article>`).join('')||'<div class="empty"><p>Ajoute les photos HD de l’invité et de l’hôte.</p></div>'}</div><div class="section-head" style="margin-top:35px"><h2>Le langage visuel WOR</h2><span class="badge">Archives · Candace</span></div><div class="library-grid">${['thumb-payouts','ref-story','ref-spotify'].map(id=>`<article class="library-item"><img src="${seed[id].src}" alt="${esc(seed[id].label)}"><div><h3>${esc(seed[id].label)}</h3><p>Référence existante · ${seed[id].width} × ${seed[id].height}</p></div></article>`).join('')}</div>`;}
 if(view==='feedback'){const comments=allComments().filter(x=>x.e.id===ep().id);html=head('LA BOUCLE DE RETOURS','Le détail fait la différence.','Chaque retour reste attaché à son image, sa position et sa version.',`<button class="button" id="export-feedback">↓ Exporter les retours</button>`)+episodeLine()+`<div class="panel"><h3>Retours prêts à reprendre</h3><p>${server?'Les retours sont aussi enregistrés sur disque dans data/retours-a-traiter.txt.':'Les retours sont enregistrés dans ce navigateur. Exporte-les pour me les transmettre.'} Une retouche IA nécessite encore une reprise dans Codex ; elle ne se lance pas depuis ce prototype.</p></div>`+(comments.length?comments.map(({a,v,i,c})=>`<article class="feedback-item"><img data-preview="${a.id}" data-version="${v.id}" alt="${esc(a.name)}"><div class="feedback-body"><span class="meta-caps">${esc(label(a.kind))} · V${String(i+1).padStart(2,'0')} · ${esc(c.category)}</span><p>${esc(c.text)}</p><span class="muted">${fmt(c.created)} · ${c.x==null?'Retour général':`Repère ${c.number} (${Math.round(c.x*100)} %, ${Math.round(c.y*100)} %)`}</span></div><span class="badge ${c.resolved?'green':'orange'}">${c.resolved?'Traité':'À reprendre'}</span><button class="button small" data-open="${a.id}" data-version="${v.id}">Ouvrir ↗</button></article>`).join(''):'<div class="empty"><h2>Le regard avant les mots.</h2><p>Ouvre un thumbnail, clique sur un détail et laisse ton premier retour.</p><button class="button" id="back-board">Voir les thumbnails →</button></div>');}
 if(view==='rules'){html=head('LA DIRECTION CRÉATIVE','Simple à utiliser. Fidèle à WOR.','Les repères qui suivent chaque visuel, du premier master au dernier export.')+`<div class="rules-grid"><section class="panel"><div class="meta-caps">TEXTURE DES EXPORTS</div><div class="rule-value">3<span style="font-size:25px"> %</span></div><h3>Un grain fin, monochrome.</h3><p>Ajouté au rendu de chaque image. Les masters restent intacts ; les exports successifs ne cumulent pas le grain.</p><p class="muted">Définition du prototype : bruit uniforme de −3 % à +3 % de l’échelle RGB, identique sur les trois canaux. Ce réglage ne peut pas corriger à lui seul un visage déjà artificiel.</p></section><section class="panel"><div class="meta-caps">PORTRAITS</div><h2 style="margin-top:22px">La photo reste la référence.</h2><p>Préserver l’identité, l’expression, les cheveux et les vêtements. Repartir des originaux si la peau dérive ; pas de lissage ni de netteté artificielle.</p><p>Spotify : aucun micro, bras, câble ou support. Cette vérification reste visuelle ; le prototype ne les retire pas automatiquement.</p></section><section class="panel"><div class="meta-caps">ENCHAÎNEMENT</div><h2 style="margin-top:22px">D’abord choisir. Ensuite décliner.</h2><p>Importer un thumbnail → examiner et annoter → valider → créer une Story et un Spotify → vérifier → exporter.</p><p>Les déclinaisons locales réutilisent le thumbnail complet dans des mises en page. Une recomposition créative des portraits passe par une retouche IA, puis l’import d’une nouvelle version.</p></section><section class="panel"><div class="meta-caps">MARQUE & TEXTE</div><h2 style="margin-top:22px">Un atelier blanc. Des visuels WOR.</h2><p>Interface blanche, texte noir, Helvetica / Arial. Les créations gardent leurs références WOR : anthracite, blanc et rouge.</p><p>Échanges en français ; textes publics en anglais. Conserver les titres exacts et les faits sourcés. Ne pas confondre payouts, profits et capital alloué.</p></section><section class="panel"><div class="meta-caps">FORMATS</div><h2 style="margin-top:22px">Les bonnes dimensions.</h2><p>Thumbnail : 3840 × 2160<br>Story : 1080 × 1920<br>Spotify : 1080 × 1080</p><p>Une source trop petite sera indiquée comme agrandie dans le manifeste d’export. Les anciennes versions restent consultables.</p></section><section class="panel"><div class="meta-caps">PROCHAINE EXTENSION</div><h2 style="margin-top:22px">WOR d’abord.</h2><p>Ce pilote couvre uniquement Words of Rizdom. PFT et CF pourront disposer de leurs propres références, règles et formats après ce test.</p><button class="button" id="mode-help">Fonctionnement de ce pilote ↗</button></section></div>`;}
 if(view==='ab')html=WORLab.render();if(view==='titles')html=WORTitles.render();if(view==='youtube')html=WORFeed.render();$('#main').innerHTML=html;wireMain();if(view==='ab')WORLab.wire();if(view==='titles')WORTitles.wire();if(view==='youtube')WORFeed.wire();paintImages();}
function on(id,fn){const el=$('#'+id);if(el)el.onclick=fn}
function wireMain(){on('new-episode',()=>briefForm(true));on('edit-brief',()=>briefForm(false));on('import-thumb',()=>askUpload('thumbnail'));on('empty-import',()=>askUpload('thumbnail'));on('prepare-brief',exportBrief);on('import-sources',()=>askUpload('source'));on('import-source-more',()=>askUpload('source'));on('generate',generate);on('step-thumb',()=>$('#thumbnail-grid')?.scrollIntoView({behavior:'smooth'}));on('step-derive',()=>$('#derivatives-heading')?.scrollIntoView({behavior:'smooth'}));on('step-export',exportPack);on('back-board',()=>navigate('board'));on('mode-help',help);on('export-feedback',()=>download(feedbackText(),`WOR_${safe(ep().name)}_retours.txt`));const s=$('#episode-select');if(s)s.onchange=()=>{activeId=s.value;persist();render()};$$('[data-open]',$('#main')).forEach(b=>b.onclick=()=>openEditor(b.dataset.open,b.dataset.version));$$('[data-select]',$('#main')).forEach(b=>b.onclick=async()=>{const a=assets().find(a=>a.id===b.dataset.select);ep().selected={assetId:a.id,versionId:latest(a).id};await persist();render();toast('Direction sélectionnée. Valide-la pour préparer les deux formats.');});const grid=$('#thumbnail-grid');if(grid){grid.ondragover=e=>{e.preventDefault();grid.classList.add('drop-active')};grid.ondragleave=()=>grid.classList.remove('drop-active');grid.ondrop=e=>{e.preventDefault();grid.classList.remove('drop-active');importFiles(e.dataTransfer.files,'thumbnail')}}}
function form(html){$('#form-content').innerHTML=html;if(!$('#form-dialog').open)$('#form-dialog').showModal();on('close-form',()=>$('#form-dialog').close());on('cancel-form',()=>$('#form-dialog').close())}
function briefForm(isNew){const e=isNew?{}:ep();form(`<div class="dialog-top"><h2>${isNew?'Un nouvel épisode':'Le brief de l’épisode'}</h2><button class="icon-button" id="close-form" aria-label="Fermer">×</button></div><p>Les sources au même endroit. Les retours directement sur les visuels.</p><form id="brief-form"><label class="field">Nom de l’invité<input id="guest-name" required maxlength="80" value="${esc(e.name||'')}" placeholder="Nom complet"></label><label class="field">Sujet / titre de travail<input id="episode-subject" maxlength="200" value="${esc(e.subject||'')}" placeholder="Le sujet de cet épisode"></label><label class="field">Lien Frame.io<input type="url" id="frameio" value="${esc(e.frameio||'')}" placeholder="https://next.frame.io/…"></label><label class="field">Transcript / notes de l’épisode<textarea id="transcript" rows="5" placeholder="Colle le transcript ou les passages utiles ici.">${esc(e.transcript||'')}</textarea></label><label class="field">Ou importer un transcript TXT<input type="file" id="transcript-file" accept=".txt,text/plain"></label><p class="inline-note">Frame.io sert de référence au brief. La collecte de photos via Download Still se fait encore dans le navigateur avec Codex.</p><div class="form-actions"><button type="button" class="button" id="cancel-form">Annuler</button><button class="button primary" type="submit">${isNew?'Créer l’épisode':'Enregistrer le brief'} →</button></div></form>`);on('cancel-form',()=>$('#form-dialog').close());$('#transcript-file').onchange=async ev=>{const f=ev.target.files[0];if(f){if(f.size>2e6)return toast('Transcript limité à 2 Mo.');$('#transcript').value=await f.text()}};$('#brief-form').onsubmit=async ev=>{ev.preventDefault();const fields={name:$('#guest-name').value.trim(),subject:$('#episode-subject').value.trim(),frameio:$('#frameio').value.trim(),transcript:$('#transcript').value};if(!fields.name)return;if(isNew){const entry={id:uid(),created:date(),...fields,assets:[],sources:[],selected:null};state.episodes.push(entry);activeId=entry.id}else Object.assign(ep(),fields);await persist();$('#form-dialog').close();view='board';render();toast('Brief enregistré.')};}
function help(){form(`<div class="dialog-top"><h2>Ton atelier, en local.</h2><button class="icon-button" id="close-form" aria-label="Fermer">×</button></div><p>Cette version utilise les vrais visuels Candace pour tester le parcours WOR.</p><div class="panel"><h3>Déjà utilisable</h3><p>Importer des images et de nouvelles versions, annoter un détail, comparer avant/après, valider, préparer les formats Story et Spotify, appliquer le grain 3 % et télécharger les PNG.</p></div><div class="panel"><h3>Le laboratoire de présélection</h3><p>Importe jusqu’à 20 images, compare un titre commun ou plusieurs titres, puis lance une analyse visuelle via ton compte Codex. Choisis un top 3 ou un top 5, puis ajuste librement la sélection. L’onglet Titres compare les formulations sans image. Le site calcule aussi 1 000 variations des poids des critères. Ce ne sont pas des spectateurs simulés ni une prévision de clics. Les images et le brief sont transmis à OpenAI uniquement au lancement de l’analyse.</p></div><div class="panel"><h3>Pour les retouches créatives par IA</h3><p>La création et la retouche d’images ne sont pas encore connectées. Les boutons préparent des mises en page et sauvegardent tes instructions. Pour que je réalise une retouche, demande-moi de reprendre les retours du studio, puis importe le nouveau visuel dans sa version.</p></div><p>${server?'La session et les retours sont sauvegardés sur disque dans le dossier data du studio.':'En ouverture HTML directe, la session reste dans ce navigateur. Utilise Sauvegarder pour conserver une copie transportable.'}</p><button class="button full" id="restore">↑ Restaurer une sauvegarde</button>`);on('restore',()=>$('#restore-input').click());}
function askUpload(intent,assetId=null){uploadIntent={intent,assetId};$('#file-input').multiple=intent!=='version';$('#file-input').value='';$('#file-input').click()}
const safe=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]/g,'_').slice(0,70);
async function fileData(f){if(!['image/jpeg','image/png','image/webp'].includes(f.type))throw Error('Formats acceptés : PNG, JPEG et WebP.');if(f.size>20*1024*1024)throw Error('Une image doit peser moins de 20 Mo.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Lecture du fichier impossible'));r.readAsDataURL(f)});const im=await loadImage(data);if(im.width*im.height>40e6)throw Error('Image limitée à 40 mégapixels.');return {data,width:im.width,height:im.height}}
async function importFiles(files,intent,assetId){if(busy)return;busy=true;let count=0;try{for(const f of [...files].slice(0,12)){const data=await fileData(f);if(intent==='source')ep().sources.push({id:uid(),name:f.name,...data});else if(intent==='version'){const a=assets().find(x=>x.id===assetId);a.versions.push({id:uid(),created:date(),...data,status:'review',comments:[],label:'Version importée'});if(a.kind==='thumbnail'&&ep().selected?.assetId===a.id)ep().selected=null;count++;break}else{assets().push({id:uid(),kind:intent,name:f.name.replace(/\.[^.]+$/,''),headline:'',versions:[{id:uid(),created:date(),...data,label:'Import',status:'review',comments:[]}]})}count++}await persist();render();if(intent==='version')openEditor(assetId);toast(`${count} image${count>1?'s':''} importée${count>1?'s':''}.`)}catch(e){toast(e.message)}finally{busy=false}}
function wrap(ctx,text,width,size,maxLines){const words=text.split(/\s+/);for(let fs=size;fs>=24;fs-=2){ctx.font=`600 ${fs}px Arial`;let lines=[''];for(const word of words){const i=lines.length-1,test=lines[i]?lines[i]+' '+word:word;if(ctx.measureText(test).width>width&&lines[i])lines.push(word);else lines[i]=test}if(lines.length<=maxLines&&lines.every(l=>ctx.measureText(l).width<=width))return {lines,size:fs}}throw Error('Le titre est trop long pour cette composition.');}
async function compose(v,kind,e){const [w,h]=dims(kind),c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d');ctx.fillStyle='#111211';ctx.fillRect(0,0,w,h);const glow=ctx.createRadialGradient(0,0,0,0,0,w);glow.addColorStop(0,'#731910');glow.addColorStop(1,'#111211');ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);ctx.fillStyle='#fff';ctx.fillRect(72,kind==='story'?175:80,194,79);ctx.fillStyle='#161616';ctx.font='bold 33px Arial';ctx.fillText('words of',82,kind==='story'?207:112);ctx.fillText('rizdom',82,kind==='story'?238:143);ctx.fillStyle='#fff';ctx.fillRect(301,kind==='story'?177:82,2,74);const name=wrap(ctx,e.name,660,40,1);ctx.font=`400 ${name.size}px Arial`;ctx.fillText(name.lines[0],334,kind==='story'?227:132);const im=await loadImage(source(v));const boxY=kind==='story'?525:270,boxH=kind==='story'?810:608;fit(ctx,im,0,boxY,w,boxH);ctx.fillStyle='#e23625';ctx.fillRect(72,kind==='story'?365:211,70,4);ctx.fillStyle='#fff';ctx.font='24px Arial';ctx.fillText('WORDS OF RIZDOM',164,kind==='story'?375:221);if(kind==='story'){ctx.font='bold 62px Arial';ctx.fillText('FULL PODCAST',72,1495);ctx.font='27px Arial';ctx.fillStyle='#cececb';ctx.fillText('YouTube  /  Spotify',74,1550);ctx.strokeStyle='#ffffff38';ctx.beginPath();ctx.moveTo(72,1625);ctx.lineTo(1008,1625);ctx.stroke();ctx.font='24px Arial';ctx.fillStyle='#eee';ctx.fillText(e.name,72,1680)}else{ctx.font='26px Arial';ctx.fillStyle='#cececb';ctx.fillText('THE FULL CONVERSATION',72,971)}if(v.grainBaked){grain(ctx,w,h);fit(ctx,im,0,boxY,w,boxH)}return c;}
async function generate(){if(busy)return;const a=selected();if(!a)return toast('Choisis d’abord un thumbnail.');const v=version(a,ep().selected.versionId);if(v.comments.some(c=>!c.resolved))return toast('Traite les retours ouverts sur cette version avant de la valider.');busy=true;const b=$('#generate');if(b){b.disabled=true;b.textContent='Préparation…'}try{const additions=[];for(const kind of ['story','spotify']){const existing=assets().find(x=>x.kind===kind&&x.parentAssetId===a.id&&x.parentVersionId===v.id);if(existing)continue;const canvas=await compose(v,kind,ep());additions.push({id:uid(),kind,name:`${label(kind)} · ${a.name}`,headline:a.headline,parentAssetId:a.id,parentVersionId:v.id,versions:[{id:uid(),created:date(),data:canvas.toDataURL('image/png'),width:canvas.width,height:canvas.height,label:'Mise en page locale',status:'review',comments:[],generated:true,grainBaked:!!v.grainBaked}]})}v.status='approved';assets().push(...additions);await persist();render();$('#derivatives-heading').scrollIntoView({behavior:'smooth'});toast(additions.length?'Story et Spotify préparés. Examine-les avant export.':'Les déclinaisons de cette version sont déjà prêtes.')}catch(e){toast(e.message);render()}finally{busy=false}}
function openEditor(id,vid){editorAsset=assets().find(a=>a.id===id);if(!editorAsset)return;editorVersion=version(editorAsset,vid);draftPin=null;editorTab='feedback';renderEditor();if(!$('#editor').open)$('#editor').showModal()}
function renderEditor(){const a=editorAsset,v=editorVersion;$('#editor-content').innerHTML=`<div class="editor-header"><div><h2>${esc(a.name)}</h2><span class="muted">${label(a.kind)} · ${versionLabel(a,v)} · ${v.width} × ${v.height} px</span></div><div class="section-tools">${statusBadge(v)}<button class="button small" id="export-image">↓ PNG</button><button class="icon-button" id="close-editor" aria-label="Fermer l’éditeur">×</button></div></div><div class="editor-layout"><section class="canvas-area"><div class="canvas-toolbar"><button class="button small ${mobile?'':'green'}" id="desktop-view">Grand format</button><button class="button small ${mobile?'green':''}" id="mobile-view">Mobile</button><span>◌ Grain 3 % · aperçu</span></div><div class="image-stage-wrap"><div class="image-stage ${mobile?'mobile':''}" id="image-stage" tabindex="0" role="button" aria-label="Ajouter un repère visuel au centre avec Entrée, ou cliquer sur l’image"><img id="editor-img" alt="${esc(a.name)}">${v.comments.filter(c=>c.x!=null&&!c.resolved).map(c=>`<button class="pin" data-pin="${c.id}" style="left:${c.x*100}%;top:${c.y*100}%" aria-label="Retour ${c.number} : ${esc(c.text)}">${c.number}</button>`).join('')}${draftPin?`<span class="pin draft" style="left:${draftPin.x*100}%;top:${draftPin.y*100}%">＋</span>`:''}</div></div><p class="annotation-help">Clique sur un détail de l’image, puis décris ce que tu veux changer.</p></section><aside class="editor-side"><div class="tabs"><button class="${editorTab==='feedback'?'active':''}" id="tab-feedback">Retours (${v.comments.length})</button><button class="${editorTab==='versions'?'active':''}" id="tab-versions">Versions (${a.versions.length})</button></div>${editorTab==='feedback'?`<h3>Ton regard, précisément.</h3><p id="pin-info">${draftPin?'Repère placé · '+Math.round(draftPin.x*100)+' %, '+Math.round(draftPin.y*100)+' %':'Retour général, ou clique sur l’image.'}</p><div class="chips">${['Général','Peau naturelle','Texte','Cadrage','Couleurs'].map(x=>`<button class="chip ${category===x?'active':''}" data-category="${x}">${x}</button>`).join('')}</div><label class="field">Ce qu’il faut ajuster<textarea id="comment-text" placeholder="Ex. Garde cette expression, mais repars de la photo originale pour la peau."></textarea></label><button class="button primary full" id="add-comment">Enregistrer le retour ↗</button><p class="inline-note">Le retour est conservé pour la retouche. Le pilote ne lance pas de génération IA.</p><div id="comments">${v.comments.map(c=>`<article class="comment ${c.resolved?'resolved':''}" id="comment-${c.id}"><small>${c.x!=null?'REPÈRE '+c.number+' · ':''}${esc(c.category)} · ${fmt(c.created)}</small><p>${esc(c.text)}</p><button class="text-button" data-resolve="${c.id}">${c.resolved?'↺ Rouvrir le retour':'✓ Marquer comme traité'}</button></article>`).join('')}</div><button class="button full green" id="approve-image" style="margin-top:18px">${v.status==='approved'?'↺ Remettre en révision':'✓ Valider cette version'}</button>`:`<h3>Une histoire, version par version.</h3><p>Chaque nouvelle version est conservée séparément.</p>${a.versions.map(ver=>`<button class="version-row ${v.id===ver.id?'active':''}" data-v="${ver.id}"><img data-version-preview="${ver.id}" alt="${versionLabel(a,ver)}"><span>${versionLabel(a,ver)}<small>${esc(ver.label)} · ${fmt(ver.created)}</small></span></button>`).join('')}<button class="button full" id="import-version">＋ Importer une nouvelle version</button><label class="field"><input type="checkbox" id="baked-grain" ${v.grainBaked?'checked':''} style="width:auto;display:inline;margin-right:8px">Cette source contient déjà le grain final 3 %</label><p class="muted">Évite de rajouter le grain à un export déjà traité.</p>${a.versions.length>1?'<label class="field">Comparer à la première version<input type="range" id="compare-range" min="0" max="100" value="100"><small class="muted">Gauche : première version · Droite : version affichée</small></label>':''}<label class="field">Nom du visuel<input id="asset-name" maxlength="100" value="${esc(a.name)}"></label><button class="button small" id="rename-asset">Renommer</button>${a.kind!=='thumbnail'?'<p class="inline-note">Cette composition conserve le thumbnail complet. Pour un autre cadrage ou des portraits recomposés, importe le rendu retouché en nouvelle version.</p>':''}`}</aside></div>`;
 preview(a,v).then(url=>{if($('#editor-img'))$('#editor-img').src=url}).catch(e=>toast(e.message));on('close-editor',()=>$('#editor').close());on('desktop-view',()=>{mobile=false;renderEditor()});on('mobile-view',()=>{mobile=true;renderEditor()});on('tab-feedback',()=>{editorTab='feedback';draftPin=null;renderEditor()});on('tab-versions',()=>{editorTab='versions';draftPin=null;renderEditor()});on('export-image',()=>exportImage(a,v));on('import-version',()=>askUpload('version',a.id));on('rename-asset',async()=>{const name=$('#asset-name').value.trim();if(name){a.name=name;await persist();render();renderEditor()}});on('add-comment',addComment);on('approve-image',async()=>{if(v.status==='approved')v.status='review';else{if(v.comments.some(c=>!c.resolved))return toast('Traite les retours ouverts avant de valider.');v.status='approved';if(a.kind==='thumbnail')ep().selected={assetId:a.id,versionId:v.id}}await persist();render();renderEditor();toast('Statut mis à jour.')});
 $$('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;$$('[data-category]').forEach(x=>x.classList.toggle('active',x===b))});$$('[data-resolve]').forEach(b=>b.onclick=async()=>{const c=v.comments.find(c=>c.id===b.dataset.resolve);c.resolved=!c.resolved;if(!c.resolved)v.status='changes';await persist();render();renderEditor()});$$('[data-v]').forEach(b=>b.onclick=()=>{editorVersion=version(a,b.dataset.v);draftPin=null;renderEditor()});$$('[data-version-preview]').forEach(async im=>{im.src=await preview(a,version(a,im.dataset.versionPreview))});$$('[data-pin]').forEach(b=>b.onclick=e=>{e.stopPropagation();if(editorTab!=='feedback'){editorTab='feedback';renderEditor()}$('#comment-'+b.dataset.pin)?.scrollIntoView({behavior:'smooth',block:'center'})});
 const stage=$('#image-stage');function place(x,y){if(editorTab!=='feedback')return;draftPin={x:Math.max(0,Math.min(1,x)),y:Math.max(0,Math.min(1,y))};stage.querySelector('.pin.draft')?.remove();const p=document.createElement('span');p.className='pin draft';p.textContent='＋';p.style.left=draftPin.x*100+'%';p.style.top=draftPin.y*100+'%';stage.appendChild(p);$('#pin-info').textContent=`Repère placé · ${Math.round(x*100)} %, ${Math.round(y*100)} %`;$('#comment-text')?.focus()};stage.onclick=e=>{if(e.target.closest('.pin'))return;const r=$('#editor-img').getBoundingClientRect();place((e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height)};stage.onkeydown=e=>{if(e.key==='Enter'&&e.target===stage){e.preventDefault();place(.5,.5)}};
 const baked=$('#baked-grain');if(baked)baked.onchange=async()=>{v.grainBaked=baked.checked;previewCache.delete(v.id);await persist();render();renderEditor()};const range=$('#compare-range');if(range){range.oninput=async()=>{let layer=$('.compare',stage);if(!layer){layer=document.createElement('div');layer.className='compare';const img=document.createElement('img');img.alt='Première version';img.src=await preview(a,a.versions[0]);layer.appendChild(img);stage.appendChild(layer)}layer.style.clipPath=`inset(0 ${100-Number(range.value)}% 0 0)`};range.value=0;}
}
async function addComment(){const text=$('#comment-text').value.trim();if(!text)return toast('Ajoute quelques mots pour préciser le retour.');const v=editorVersion;v.comments.push({id:uid(),number:v.comments.length+1,text,category,created:date(),resolved:false,x:draftPin?.x??null,y:draftPin?.y??null});v.status='changes';draftPin=null;await persist();render();renderEditor();toast('Retour enregistré sur cette version.')}
async function exportImage(a,v){try{toast('Préparation du PNG avec grain 3 %…');const c=await raster(v,a.kind);const blob=await new Promise(r=>c.toBlob(r,'image/png'));if(!blob)throw Error('Export impossible');download(blob,`WOR_${safe(ep().name)}_${safe(label(a.kind))}_${versionLabel(a,v)}_grain3.png`);toast('PNG exporté. Le master reste intact.')}catch(e){toast(e.message)}}
function feedbackText(){return ['WOR STUDIO — RETOURS À TRAITER','Généré le '+new Date().toLocaleString('fr-FR'),'Les retours ne sont pas envoyés automatiquement à un moteur IA.','Règles : photos originales, identité préservée, corrections ciblées, versions conservées, grain final 3 %.',...allComments().filter(x=>x.e.id===ep().id).map(({a,v,c})=>`\n${ep().name} / ${label(a.kind)} / ${a.name} / ${versionLabel(a,v)}\n${c.resolved?'TRAITÉ':'À TRAITER'} — ${c.category}\n${c.x==null?'Retour général':`Repère ${c.number} — x=${(c.x*100).toFixed(1)} %, y=${(c.y*100).toFixed(1)} % (origine haut gauche)`}\n${c.text}\nVersion ID : ${v.id}`)].join('\n')}
function exportBrief(){download(['BRIEF WOR — '+ep().name,'Sujet : '+ep().subject,'Frame.io : '+ep().frameio,'Photos importées : '+ep().sources.map(x=>x.name).join(', '),'\nProduire le thumbnail en premier à partir des sources originales. Après validation, créer une Story 1080x1920 et un Spotify 1080x1080. Conserver les visages et les titres exacts, ne pas inventer de faits. Aucun micro/support/câble sur Spotify. Ajouter 3 % de grain à la finition. Versions séparées.','\nTRANSCRIPT\n'+ep().transcript,'\n'+feedbackText()].join('\n'),`WOR_${safe(ep().name)}_brief.txt`);toast('Brief préparé pour une reprise dans Codex.')}
// Minimal ZIP writer, store method (PNG files are already compressed).
const crcTable=Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0});
function crc32(bytes){let c=0xffffffff;for(const b of bytes)c=crcTable[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0}
function zipBlob(files){let offset=0;const parts=[],central=[];const enc=new TextEncoder();for(const f of files){const name=enc.encode(f.name),data=f.data,crc=crc32(data),head=new Uint8Array(30+name.length),dv=new DataView(head.buffer);dv.setUint32(0,0x04034b50,true);dv.setUint16(4,20,true);dv.setUint16(6,0x800,true);dv.setUint32(14,crc,true);dv.setUint32(18,data.length,true);dv.setUint32(22,data.length,true);dv.setUint16(26,name.length,true);head.set(name,30);parts.push(head,data);const ce=new Uint8Array(46+name.length),cv=new DataView(ce.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x800,true);cv.setUint32(16,crc,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);ce.set(name,46);central.push(ce);offset+=head.length+data.length}const size=central.reduce((n,x)=>n+x.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,files.length,true);ev.setUint16(10,files.length,true);ev.setUint32(12,size,true);ev.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/zip'})}
async function exportPack(){if(busy)return;const a=selected();if(!a)return toast('Sélectionne et valide un thumbnail pour préparer le pack.');const parent=ep().selected,items=[{a,v:version(a,parent.versionId)},...['story','spotify'].map(k=>{const a=assets().find(a=>a.kind===k&&a.parentVersionId===parent.versionId&&a.parentAssetId===parent.assetId);return a?{a,v:latest(a)}:null}).filter(Boolean)];if(items.length!==3)return toast('Prépare d’abord les déclinaisons Story et Spotify.');const unapproved=items.filter(({v})=>v.status!=='approved'||v.comments.some(c=>!c.resolved));if(unapproved.length){form(`<div class="dialog-top"><h2>Encore un dernier regard.</h2><button class="icon-button" id="close-form" aria-label="Fermer">×</button></div><p>Le pack final attend la validation de ces visuels :</p>${unapproved.map(({a,v})=>`<button class="version-row" data-check="${a.id}" data-version="${v.id}">${label(a.kind)} · ${versionLabel(a,v)} <span style="margin-left:auto">Examiner →</span></button>`).join('')}<p>Les PNG individuels restent exportables à tout moment.</p>`);$$('[data-check]').forEach(b=>b.onclick=()=>{$('#form-dialog').close();openEditor(b.dataset.check,b.dataset.version)});return}busy=true;toast('Préparation du pack final…');try{const files=[],manifest=[];for(const {a,v} of items){const c=await raster(v,a.kind),blob=await new Promise(r=>c.toBlob(r,'image/png'));if(!blob)throw Error('Échec de rendu');const name=`${label(a.kind)}_${versionLabel(a,v)}_${c.width}x${c.height}_grain3.png`;files.push({name,data:new Uint8Array(await blob.arrayBuffer())});manifest.push({file:name,sourceDimensions:[v.width,v.height],outputDimensions:[c.width,c.height],enlarged:c.width>v.width||c.height>v.height,grain:v.grainBaked?'source declared already treated':'uniform monochrome +/-3% RGB scale',versionId:v.id,parentVersionId:a.parentVersionId||null})}const enc=new TextEncoder();files.push({name:'manifest.json',data:enc.encode(JSON.stringify({episode:ep().name,created:date(),files:manifest},null,2))},{name:'retours.txt',data:enc.encode(feedbackText())});download(zipBlob(files),`WOR_${safe(ep().name)}_Pack.zip`);toast('Pack prêt : 3 PNG, manifeste et retours.')}catch(e){toast(e.message)}finally{busy=false}}
async function init(){try{db=await openDB()}catch{}let saved;try{saved=await dbRead()}catch{}if(location.protocol!=='file:'){try{const r=await fetch('/api/state');if(r.ok){const data=await r.json();server=true;token=data.token;revision=data.revision;saved=data.state||saved}}catch{}}state=validState(saved)?saved:initial();activeId=state.activeId||state.episodes[0].id;if(['board','ab','titles','youtube','library','feedback','rules'].includes(location.hash.slice(1)))view=location.hash.slice(1);render();await persist();}
$$('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));on('help',help);on('about',help);on('workspace',()=>form('<div class="dialog-top"><h2>Words of Rizdom</h2><button class="icon-button" id="close-form" aria-label="Fermer">×</button></div><p>WOR est le projet pilote actif. PFT et CF seront ajoutés après ce test, avec leurs propres références.</p>'));on('backup',async()=>{await persist();download(JSON.stringify(state,null,2),`WOR_Studio_${new Date().toISOString().slice(0,10)}.json`,'application/json');toast('Sauvegarde complète téléchargée.')});$('#file-input').onchange=e=>{if(uploadIntent)importFiles(e.target.files,uploadIntent.intent,uploadIntent.assetId)};$('#restore-input').onchange=async ev=>{try{const f=ev.target.files[0];if(!f)return;if(f.size>100*1024*1024)throw Error('Sauvegarde trop volumineuse');const s=JSON.parse(await f.text());if(!validState(s))throw Error('Ce fichier n’est pas une sauvegarde WOR Studio valide.');const merged=structuredClone(state);for(const e of s.episodes){const copy=structuredClone(e);copy.id=uid();copy.name+=' · restauré';merged.episodes.push(copy)}state=merged;activeId=state.episodes.at(-1).id;await persist();$('#form-dialog').close();view='board';render();toast('Sauvegarde restaurée en copies séparées.')}catch(e){toast(e.message)}finally{ev.target.value=''}};
window.addEventListener('error',()=>{$('#save-status').textContent='Une erreur est survenue';});init().catch(e=>{$('#main').innerHTML='<div class="empty"><h2>Le studio n’a pas pu démarrer.</h2><p>'+esc(e.message)+'</p></div>'});

function navigate(next){view=["board","ab","titles","youtube","library","feedback","rules"].includes(next)?next:"ab";history.replaceState(null,"",location.pathname+"#"+view);render();window.scrollTo({top:0,behavior:"smooth"})}
